// Clean string helper
inline string trim(string s) {
    s.erase(s.begin(), find_if(s.begin(), s.end(), [](unsigned char ch) {
        return !isspace(ch);
    }));
    s.erase(find_if(s.rbegin(), s.rend(), [](unsigned char ch) {
        return !isspace(ch);
    }).base(), s.end());
    return s;
}

inline vector<string> splitInputs(string line) {
    vector<string> res;
    string current = "";
    int brackets = 0;
    bool inQuotes = false;
    for (size_t i = 0; i < line.length(); ++i) {
        char c = line[i];
        if (c == '"' && (i == 0 || line[i-1] != '\\')) {
            inQuotes = !inQuotes;
        }
        if (!inQuotes) {
            if (c == '[' || c == '{') brackets++;
            if (c == ']' || c == '}') brackets--;
        }
        if (c == ',' && brackets == 0 && !inQuotes) {
            res.push_back(current);
            current = "";
        } else {
            current += c;
        }
    }
    if (!current.empty()) {
        res.push_back(current);
    }
    for (auto& token : res) {
        token = trim(token);
        size_t eqPos = token.find('=');
        if (eqPos != string::npos) {
            token = trim(token.substr(eqPos + 1));
        }
    }
    return res;
}

