class Parser {
    public static String trim(String s) {
        return s.trim();
    }

    public static List<String> splitInputs(String line) {
        List<String> res = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        int brackets = 0;
        boolean inQuotes = false;

        for (int i = 0; i < line.length(); ++i) {
            char c = line.charAt(i);
            if (c == '"' && (i == 0 || line.charAt(i-1) != '\\')) {
                inQuotes = !inQuotes;
            }
            if (!inQuotes) {
                if (c == '[' || c == '{') brackets++;
                if (c == ']' || c == '}') brackets--;
            }

            if (c == ',' && brackets == 0 && !inQuotes) {
                res.add(current.toString());
                current = new StringBuilder();
            } else {
                current.append(c);
            }
        }
        if (current.length() > 0) {
            res.add(current.toString());
        }

        List<String> cleaned = new ArrayList<>();
        for (String token : res) {
            token = trim(token);
            int eqPos = token.indexOf('=');
            if (eqPos != -1) {
                token = trim(token.substring(eqPos + 1));
            }
            cleaned.add(token);
        }
        return cleaned;
    }

    public static int parseInt(String s) {
        return s.isEmpty() ? 0 : Integer.parseInt(trim(s));
    }

    public static double parseDouble(String s) {
        return s.isEmpty() ? 0.0 : Double.parseDouble(trim(s));
    }

    public static boolean parseBool(String s) {
        s = trim(s).toLowerCase();
        return s.equals("true") || s.equals("1");
    }

    public static String parseString(String s) {
        s = trim(s);
        if (s.length() >= 2 && s.startsWith("\"") && s.endsWith("\"")) {
            s = s.substring(1, s.length() - 1);
        }
        return s;
    }

    public static int[] parseArrayInt(String s) {
        s = trim(s);
        if (s.isEmpty() || s.equals("[]")) return new int[0];
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);
        String[] tokens = s.split(",");
        int[] res = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            res[i] = Integer.parseInt(trim(tokens[i]));
        }
        return res;
    }

    public static List<Integer> parseListInteger(String s) {
        int[] arr = parseArrayInt(s);
        List<Integer> res = new ArrayList<>();
        for (int x : arr) res.add(x);
        return res;
    }

    public static String[] parseArrayString(String s) {
        s = trim(s);
        if (s.isEmpty() || s.equals("[]")) return new String[0];
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);

        List<String> res = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean inQuotes = false;
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            if (c == '"') inQuotes = !inQuotes;
            else if (c == ',' && !inQuotes) {
                res.add(parseString(current.toString()));
                current = new StringBuilder();
            } else {
                current.append(c);
            }
        }
        if (current.length() > 0) {
            res.add(parseString(current.toString()));
        }
        return res.toArray(new String[0]);
    }

    public static List<String> parseListString(String s) {
        return Arrays.asList(parseArrayString(s));
    }

    public static int[][] parseMatrixInt(String s) {
        s = trim(s);
        if (s.isEmpty() || s.equals("[]") || s.equals("[[]]")) return new int[0][0];
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);

        List<int[]> res = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        int brackets = 0;
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            if (c == '[') brackets++;
            if (c == ']') brackets--;
            current.append(c);
            if (c == ']' && brackets == 0) {
                res.add(parseArrayInt(current.toString()));
                current = new StringBuilder();
                if (i + 1 < s.length() && s.charAt(i+1) == ',') i++;
            }
        }
        return res.toArray(new int[0][0]);
    }

