    }

    public static ListNode parseListNode(String s) {
        int[] vals = parseArrayInt(s);
        if (vals.length == 0) return null;
        ListNode head = new ListNode(vals[0]);
        ListNode curr = head;
        for (int i = 1; i < vals.length; ++i) {
            curr.next = new ListNode(vals[i]);
            curr = curr.next;
        }
        return head;
    }

    public static TreeNode parseTreeNode(String s) {
        s = trim(s);
        if (s.isEmpty() || s.equals("[]") || s.equals("[null]")) return null;
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);

        String[] tokens = s.split(",");
        for (int i = 0; i < tokens.length; i++) tokens[i] = trim(tokens[i]);

        if (tokens.length == 0 || tokens[0].equals("null")) return null;

        TreeNode root = new TreeNode(Integer.parseInt(tokens[0]));
        Queue<TreeNode> q = new LinkedList<>();
        q.add(root);

        int i = 1;
        while (!q.isEmpty() && i < tokens.length) {
            TreeNode curr = q.poll();

            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.left = new TreeNode(Integer.parseInt(tokens[i]));
                q.add(curr.left);
            }
            i++;

            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.right = new TreeNode(Integer.parseInt(tokens[i]));
                q.add(curr.right);
            }
            i++;
        }
        return root;
    }
